    "            break\n"
    "        z[\"elts\"].append(parse_expr(p))\n"
    "    return z\n"
    "\n"
    "def parse_expr(p):\n"
    "    if at(p, \"lambda\"):\n"
    "        return parse_lambda(p)\n"
    "    return parse_ifexp(p)\n"
    "\n"
    "def parse_lambda(p):\n"
    "    x : take(p)\n"
    "    args : []\n"
    "    if not at(p, \":\"):\n"
    "        while True:\n"
    "            if at(p, \"*\"):\n"
    "                fail(p, \"variadic or keyword-only lambda parameters are unsupported\", peek(p))\n"
    "            a : need_kind(p, \"NAME\")\n"
    "            args.append(ident(p, a))\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "    if len(args) > 1:\n"
    "        fail(p, \"multi-argument lambdas are unsupported\", x)\n"
    "    need(p, \":\")\n"
    "    z : node(\"Lambda\", x)\n"
    "    z[\"args\"] : args\n"
    "    z[\"body\"] : parse_expr(p)\n"
    "    return z\n"
    "\n"
    "def parse_ifexp(p):\n"
    "    z : parse_or(p)\n"
    "    if at(p, \"if\"):\n"
    "        x : take(p)\n"
    "        q : node(\"IfExp\", x)\n"
    "        q[\"body\"] : z\n"
    "        q[\"test\"] : parse_or(p)\n"
    "        need(p, \"else\")\n"
    "        q[\"orelse\"] : parse_expr(p)\n"
    "        return q\n"
    "    if at(p, \":=\"):\n"
    "        fail(p, \"walrus operator is unsupported\", peek(p))\n"
    "    return z\n"
    "\n"
    "def parse_or(p):\n"
    "    xs : [parse_and(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"or\"):\n"
    "        take(p)\n"
    "        xs.append(parse_and(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"or\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_and(p):\n"
    "    xs : [parse_not(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"and\"):\n"
    "        take(p)\n"
    "        xs.append(parse_not(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"and\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_not(p):\n"
    "    if at(p, \"not\") and peekn(p, 1)[\"text\"] != \"in\":\n"
    "        x : take(p)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"not\"\n"
    "        z[\"value\"] : parse_not(p)\n"
    "        return z\n"
    "    return parse_compare(p)\n"
    "\n"
    "def parse_compare(p):\n"
    "    left : parse_bitor(p)\n"
    "    ops : []\n"
    "    vals : []\n"
    "    while peek(p)[\"text\"] in [\"==\", \"!=\", \"<\", \"<=\", \">\", \">=\", \"in\", \"is\"] or (at(p, \"not\") and peekn(p, 1)[\"text\"] = \"in\"):\n"
    "        x : take(p)\n"
    "        op : x[\"text\"]\n"
    "        if op = \"not\":\n"
    "            take(p)\n"
    "            op : \"not in\"\n"
    "        elif op = \"is\":\n"
    "            if at(p, \"not\"):\n"
    "                take(p)\n"
    "            fail(p, \"comparison Is is unsupported\", x)\n"
    "        ops.append(op)\n"
    "        vals.append(parse_bitor(p))\n"
    "    if len(ops) = 0:\n"
    "        return left\n"
    "    if len(ops) > 1:\n"
    "        fail(p, \"chained comparisons are unsupported\", left)\n"
    "    z : node(\"Compare\", left)\n"
    "    z[\"left\"] : left\n"
    "    z[\"op\"] : ops[0]\n"
    "    z[\"right\"] : vals[0]\n"
    "    return z\n"
    "\n"
    "def reject_bit(p, z, ops):\n"
    "    while peek(p)[\"text\"] in ops:\n"
    "        fail(p, \"bitwise operators are unsupported\", peek(p))\n"
    "    return z\n"
    "\n"
    "def parse_bitor(p):\n"
    "    return reject_bit(p, parse_shift(p), [\"|\", \"^\", \"&\"])\n"
    "\n"
    "def parse_shift(p):\n"
    "    return reject_bit(p, parse_arith(p), [\"<<\", \">>\"])\n"
    "\n"
    "def binary(p, sub, ops):\n"
    "    z : sub(p)\n"
    "    while peek(p)[\"text\"] in ops:\n"
    "        x : take(p)\n"
    "        q : node(\"BinOp\", x)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : x[\"text\"]\n"
    "        q[\"right\"] : sub(p)\n"
    "        z : q\n"
    "    return z\n"
    "\n"
    "def parse_arith(p):\n"
    "    return binary(p, parse_term, [\"+\", \"-\"])\n"
    "\n"
    "def parse_term(p):\n"
    "    return binary(p, parse_factor, [\"*\", \"/\", \"//\", \"%\", \"@\"])\n"
    "\n"
    "def parse_factor(p):\n"
    "    if peek(p)[\"text\"] in [\"+\", \"-\", \"~\"]:\n"
    "        x : take(p)\n"
    "        if x[\"text\"] = \"+\":\n"
    "            fail(p, \"unary plus is unsupported\", x)\n"
    "        if x[\"text\"] = \"~\":\n"
    "            fail(p, \"bitwise invert is unsupported\", x)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"-\"\n"
    "        z[\"value\"] : parse_factor(p)\n"
    "        return z\n"
    "    return parse_power(p)\n"
    "\n"
    "def parse_power(p):\n"
    "    z : parse_postfix(p)\n"
    "    if at(p, \"**\"):\n"
    "        x : take(p)\n"
    "        q : node(\"BinOp\", x)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : \"**\"\n"
    "        q[\"right\"] : parse_factor(p)\n"
    "        return q\n"
    "    return z\n"
    "\n"
    "def parse_postfix(p):\n"
    "    z : parse_atom(p)\n"
    "    while True:\n"
    "        if at(p, \".\"):\n"
    "            x : take(p)\n"
    "            a : need_kind(p, \"NAME\")\n"
    "            q : node(\"Attr\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"attr\"] : a[\"text\"]\n"
    "            z : q\n"
    "        elif at(p, \"(\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Call\", x)\n"
    "            q[\"func\"] : z\n"
    "            q[\"args\"] : []\n"
    "            q[\"kwargs\"] : []\n"
    "            if not at(p, \")\"):\n"
    "                while True:\n"
    "                    if at(p, \"**\"):\n"
    "                        fail(p, \"**kwargs is unsupported\", peek(p))\n"
    "                    if at(p, \"*\"):\n"
    "                        fail(p, \"*args is unsupported\", peek(p))\n"
    "                    if kind(p, \"NAME\") and peekn(p, 1)[\"text\"] = \"=\":\n"
    "                        k : take(p)\n"
    "                        ident(p, k)\n"
    "                        take(p)\n"
    "                        q[\"kwargs\"].append([k, parse_expr(p)])\n"
    "                    else:\n"
    "                        q[\"args\"].append(parse_expr(p))\n"
    "                    if not at(p, \",\"):\n"
    "                        break\n"
    "                    take(p)\n"
    "                    if at(p, \")\"):\n"
    "                        break\n"
    "            need(p, \")\")\n"
    "            z : q\n"
    "        elif at(p, \"[\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Subscript\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"slice\"] : parse_slice_list(p)\n"
    "            need(p, \"]\")\n"
    "            z : q\n"
    "        else:\n"
    "            break\n"
    "    return z\n"
    "\n"
    "def parse_slice_list(p):\n"
    "    xs : [parse_slice(p)]\n"
    "    while at(p, \",\"):\n"
    "        take(p)\n"
    "        xs.append(parse_slice(p))\n"
    "    if len(xs) = 1:\n"
    "        return xs[0]\n"
    "    z : node(\"SliceTuple\", xs[0])\n"
    "    z[\"elts\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_slice(p):\n"
    "    x : peek(p)\n"
    "    lower : None\n"
    "    if not at(p, \":\"):\n"
    "        lower : parse_expr(p)\n"
    "    if not at(p, \":\"):\n"
    "        return lower\n"
    "    take(p)\n"
    "    upper : None\n"
    "    step : None\n"
    "    if not at(p, \":\") and not at(p, \"]\") and not at(p, \",\"):\n"
    "        upper : parse_expr(p)\n"
    "    if at(p, \":\"):\n"
    "        take(p)\n"
    "        if not at(p, \"]\") and not at(p, \",\"):\n"
    "            step : parse_expr(p)\n"
    "    z : node(\"Slice\", x)\n"
    "    z[\"lower\"] : lower\n"
    "    z[\"upper\"] : upper\n"
    "    z[\"step\"] : step\n"
    "    return z\n"
    "\n"
    "def parse_atom(p):\n"
    "    x : peek(p)\n"
    "    if kind(p, \"NUMBER\"):\n"
    "        take(p)\n"
    "        if \"j\" in x[\"text\"] or \"J\" in x[\"text\"]:\n"
    "            fail(p, \"complex literals are unsupported\", x)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : x[\"text\"]\n"
    "        z[\"kind\"] : \"number\"\n"
    "        return z\n"
    "    if kind(p, \"STRING\"):\n"
    "        take(p)\n"
    "        if x[\"val\"][\"f\"]:\n"
    "            depth : 0\n"
    "            j : 0\n"
    "            while j < len(x[\"val\"][\"s\"]):\n"
    "                c : x[\"val\"][\"s\"][j]\n"
    "                if c = \"{\":\n"
    "                    if j + 1 < len(x[\"val\"][\"s\"]) and x[\"val\"][\"s\"][j + 1] = \"{\":\n"
    "                        j += 2\n"
    "                        continue\n"
    "                    depth += 1\n"
    "                elif c = \"}\":\n"
    "                    depth += -1\n"
    "                elif depth > 0 and (c = \"!\" or c = \":\"):\n"
    "                    fail(p, \"f-string conversions/format specs are unsupported\", x)\n"
    "                j += 1\n"
    "        z : node(\"FString\" if x[\"val\"][\"f\"] else \"Const\", x)\n"
    "        z[\"value\"] : x[\"val\"][\"s\"]\n"
    "        z[\"kind\"] : \"string\"\n"
    "        return z\n"
    "    if kind(p, \"NAME\"):\n"
    "        take(p)\n"
    "        if (x[\"text\"] = \"b\" or x[\"text\"] = \"B\") and kind(p, \"STRING\"):\n"
    "            fail(p, \"bytes literals are unsupported\", x)\n"
    "        if x[\"text\"] = \"await\":\n"
    "            fail(p, \"Await is unsupported\", x)\n"
    "        if x[\"text\"] = \"yield\":\n"
    "            fail(p, \"Yield is unsupported\", x)\n"
    "        z : node(\"Const\" if x[\"text\"] in [\"True\", \"False\", \"None\"] else \"Name\", x)\n"
    "        z[\"value\"] : x[\"text\"] if z[\"t\"] = \"Const\" else ident(p, x)\n"
    "        if z[\"t\"] = \"Name\":\n"
    "            x[\"text\"] : z[\"value\"]\n"
    "        return z\n"
    "    if at(p, \"(\"):\n"
    "        take(p)\n"
    "        if at(p, \")\"):\n"
    "            take(p)\n"
    "            z : node(\"Tuple\", x)\n"
    "            z[\"elts\"] : []\n"
    "            return z\n"
    "        z : parse_expr_list(p)\n"
    "        need(p, \")\")\n"
    "        return z\n"
    "    if at(p, \"[\"):\n"
    "        take(p)\n"
    "        z : node(\"List\", x)\n"
    "        z[\"elts\"] : []\n"
    "        if not at(p, \"]\"):\n"
    "            while True:\n"
    "                e : parse_expr(p)\n"
    "                if at(p, \"for\"):\n"
    "                    fail(p, \"comprehensions are unsupported\", x)\n"
    "                z[\"elts\"].append(e)\n"
    "                if not at(p, \",\"):\n"
    "                    break\n"
    "                take(p)\n"
    "                if at(p, \"]\"):\n"
    "                    break\n"
    "        need(p, \"]\")\n"
    "        return z\n"
    "    if at(p, \"{\"):\n"
    "        take(p)\n"
    "        z : node(\"Dict\", x)\n"
    "        z[\"keys\"] : []\n"
    "        z[\"values\"] : []\n"
    "        if not at(p, \"}\"):\n"
    "            while True:\n"
    "                if at(p, \"**\"):\n"
    "                    fail(p, \"dict unpacking is unsupported\", peek(p))\n"
    "                k : parse_expr(p)\n"
    "                if at(p, \"for\"):\n"
    "                    fail(p, \"comprehensions are unsupported\", x)\n"
    "                if not at(p, \":\"):\n"
    "                    fail(p, \"set literals are unsupported\", x)\n"
    "                need(p, \":\")\n"
    "                z[\"keys\"].append(k)\n"
    "                z[\"values\"].append(parse_expr(p))\n"
    "                if not at(p, \",\"):\n"
    "                    break\n"
    "                take(p)\n"
    "                if at(p, \"}\"):\n"
    "                    break\n"
    "        need(p, \"}\")\n"
    "        return z\n"
    "    fail(p, \"unsupported expression\", x)\n"
    "\n"
    "def pad(n):\n"
    "    return \"    \" * n\n"
    "\n"
    "def render(ast, state):\n"
    "    state[\"comments\"] : ast[\"comments\"]\n"
    "    state[\"inline\"] : ast[\"inline\"]\n"
    "    state[\"last_comment\"] : 0\n"
    "    state[\"filename\"] : ast[\"filename\"]\n"
    "    lines : render_body(ast[\"body\"], state, 0, True)\n"
    "    for k in state[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > state[\"last_comment\"]:\n"
    "            lines.append(state[\"comments\"][k])\n"
    "    text : \"\"\n"
    "    for line in lines:\n"
    "        if line != \"\":\n"
    "            text += line + \"\\n\"\n"
    "    return text\n"
    "\n"
    "def before_comments(st, line, indent):\n"
    "    out : []\n"
    "    for k in st[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > st[\"last_comment\"] and kn < line:\n"
    "            out.append(pad(indent) + st[\"comments\"][k])\n"
    "            st[\"last_comment\"] : kn\n"
    "    return out\n"
    "\n"
    "def render_body(body, st, indent, doc_ok):\n"
    "    out : []\n"
    "    i : 0\n"
    "    while i < len(body):\n"
    "        s : body[i]\n"
    "        cs : before_comments(st, s[\"line\"], indent)\n"
    "        for c in cs:\n"
    "            out.append(c)\n"
    "        if doc_ok and i = 0 and s[\"t\"] = \"Expr\" and s[\"value\"][\"t\"] = \"Const\" and s[\"value\"][\"kind\"] = \"string\":\n"
    "            parts : re_split(\"\\n\", s[\"value\"][\"value\"])\n"
    "            for q in parts:\n"
    "                out.append(pad(indent) + (\"# \" + q if len(q) > 0 else \"#\"))\n"
    "        else:\n"
    "            rs : render_stmt(s, st, indent)\n"
    "            key : str(s[\"line\"])\n"
    "            if key in st[\"inline\"]:\n"
    "                rs[0] : rs[0] + \"  \" + st[\"inline\"][key]\n"
    "            for q in rs:\n"
    "                if q != \"\":\n"
    "                    out.append(q)\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def render_stmt(s, st, ind):\n"
    "    p : pad(ind)\n"
    "    t : s[\"t\"]\n"
    "    if t = \"Assign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" : \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"AugAssign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" \" + s[\"op\"] + \" \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"Return\":\n"
    "        return [p + (\"return\" if s[\"value\"] = None else \"return \" + expr_text(s[\"value\"], st))]\n"
    "    if t = \"break\" or t = \"continue\" or t = \"pass\":\n"
    "        return [p + t]\n"
    "    if t = \"Import\":\n"
    "        return [\"\" if s[\"erase\"] else p + \"import \" + s[\"name\"]]\n"
    "    if t = \"Assert\":\n"
    "        return [p + \"assert(\" + expr_text(s[\"test\"], st) + \")\"]\n"
    "    if t = \"Expr\":\n"
    "        return [p + expr_text(s[\"value\"], st)]\n"
    "    if t = \"FunctionDef\":\n"
    "        out : []\n"
    "        for d in s[\"decorators\"]:\n"
    "            out.append(p + \"@\" + expr_text(d, st))\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(s[\"args\"]):\n"
    "            q : s[\"args\"][i]\n"
    "            if s[\"defaults\"][i] != None:\n"
    "                q += \":\" + expr_text(s[\"defaults\"][i], st)\n"
    "            parts.append(q)\n"
    "            i += 1\n"
    "        out.append(p + \"def \" + s[\"name\"] + \"(\" + join_text(parts, \", \") + \"):\")\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, True):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    if t = \"If\":\n"
    "        out : [p + \"if \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        for e in s[\"elifs\"]:\n"
    "            out.append(p + \"elif \" + expr_text(e[\"test\"], st) + \":\")\n"
    "            for q in render_body(e[\"body\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        if len(s[\"orelse\"]) > 0:\n"
    "            out.append(p + \"else:\")\n"
    "            for q in render_body(s[\"orelse\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        return out\n"
    "    if t = \"While\":\n"
    "        out : [p + \"while \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    if t = \"For\":\n"
    "        out : [p + \"for \" + target_text(s[\"target\"], st) + \" in \" + expr_text(s[\"iter\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    return []\n"
    "\n"
    "def join_text(xs, sep):\n"
    "    out : \"\"\n"
    "    i : 0\n"
    "    while i < len(xs):\n"
    "        if i > 0:\n"
    "            out += sep\n"
    "        out += xs[i]\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def target_text(x, st):\n"
    "    if x[\"t\"] = \"Tuple\" or x[\"t\"] = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(target_text(e, st))\n"
    "        return join_text(parts, \", \")\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def slice_text(x, st):\n"
    "    if x[\"t\"] = \"Slice\":\n"
    "        a : \"\" if x[\"lower\"] = None else expr_text(x[\"lower\"], st)\n"
    "        b : \"\" if x[\"upper\"] = None else expr_text(x[\"upper\"], st)\n"
    "        q : a + \":\" + b\n"
    "        if x[\"step\"] != None:\n"
    "            q += \":\" + expr_text(x[\"step\"], st)\n"
    "        return q\n"
    "    if x[\"t\"] = \"SliceTuple\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(slice_text(e, st))\n"
    "        return join_text(parts, \", \")\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def expr_text(x, st):\n"
    "    t : x[\"t\"]\n"
    "    if t = \"Name\":\n"
    "        return x[\"value\"]\n"
    "    if t = \"Const\":\n"
    "        if x[\"kind\"] = \"string\":\n"
    "            return quote_string(x[\"value\"])\n"
    "        return x[\"value\"]\n"
    "    if t = \"FString\":\n"
    "        return \"f\" + quote_string(x[\"value\"])\n"
    "    if t = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"[\" + join_text(parts, \", \") + \"]\"\n"
    "    if t = \"Tuple\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        if len(parts) = 1:\n"
    "            return \"(\" + parts[0] + \",)\"\n"
    "        return \"(\" + join_text(parts, \", \") + \")\"\n"
    "    if t = \"Dict\":\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(x[\"keys\"]):\n"
    "            parts.append(expr_text(x[\"keys\"][i], st) + \": \" + expr_text(x[\"values\"][i], st))\n"
    "            i += 1\n"
    "        return \"{\" + join_text(parts, \", \") + \"}\"\n"
    "    if t = \"Attr\":\n"
    "        if x[\"value\"][\"t\"] = \"Name\" and x[\"value\"][\"value\"] in st[\"aliases\"]:\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": \" + st[\"aliases\"][x[\"value\"][\"value\"]] + \".\" + x[\"attr\"] + \" is unsupported outside a mapped call\"\n"
    "        return expr_text(x[\"value\"], st) + \".\" + x[\"attr\"]\n"
    "    if t = \"Subscript\":\n"
    "        return expr_text(x[\"value\"], st) + \"[\" + slice_text(x[\"slice\"], st) + \"]\"\n"
    "    if t = \"Unary\":\n"
    "        return \"(\" + (\"not \" if x[\"op\"] = \"not\" else \"-\") + expr_text(x[\"value\"], st) + \")\"\n"
    "    if t = \"BinOp\":\n"
    "        if x[\"op\"] = \"@\":\n"
    "            return \"mmul(\" + expr_text(x[\"left\"], st) + \", \" + expr_text(x[\"right\"], st) + \")\"\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + x[\"op\"] + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"BoolOp\":\n"
    "        parts : []\n"
    "        for e in x[\"values\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"(\" + join_text(parts, \" \" + x[\"op\"] + \" \") + \")\"\n"
    "    if t = \"Compare\":\n"
    "        op : \"=\" if x[\"op\"] = \"==\" else x[\"op\"]\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + op + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"IfExp\":\n"
    "        return expr_text(x[\"body\"], st) + \" if \" + expr_text(x[\"test\"], st) + \" else \" + expr_text(x[\"orelse\"], st)\n"
    "    if t = \"Lambda\":\n"
    "        return \"(lambda \" + join_text(x[\"args\"], \", \") + \": \" + expr_text(x[\"body\"], st) + \")\"\n"
    "    if t = \"Call\":\n"
    "        lowered : lower_call(x, st)\n"
    "        if lowered != None:\n"
    "            return lowered\n"
    "        parts : []\n"
    "        for e in x[\"args\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        for kv in x[\"kwargs\"]:\n"
    "            parts.append(kv[0][\"text\"] + \":\" + expr_text(kv[1], st))\n"
    "        return expr_text(x[\"func\"], st) + \"(\" + join_text(parts, \", \") + \")\"\n"
    "    return \"\"\n"
    "\n"
    "def lower_call(x, st):\n"
    "    f : x[\"func\"]\n"
    "    if f[\"t\"] != \"Attr\" or f[\"value\"][\"t\"] != \"Name\":\n"
    "        return None\n"
    "    alias : f[\"value\"][\"value\"]\n"
    "    if not alias in st[\"aliases\"]:\n"
    "        return None\n"
    "    mod : st[\"aliases\"][alias]\n"
    "    name : f[\"attr\"]\n"
    "    if mod = \"numpy\":\n"
    "        if name = \"array\" or name = \"asarray\":\n"
    "            if len(x[\"args\"]) != 1 or len(x[\"kwargs\"]) != 0:\n"
    "                raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": numpy.\" + name + \" requires one argument without dtype/options\"\n"
    "            return expr_text(x[\"args\"][0], st)\n"
    "        maps : {\"sum\":\"sum\", \"mean\":\"avg\", \"min\":\"min\", \"max\":\"max\", \"dot\":\"dot\",\n"
    "                \"matmul\":\"mmul\", \"abs\":\"abs\", \"sqrt\":\"sqrt\", \"exp\":\"exp\", \"log\":\"log\",\n"
    "                \"sin\":\"sin\", \"cos\":\"cos\", \"tan\":\"tan\"}\n"
    "        if not name in maps:\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": numpy.\" + name + \" is unsupported\"\n"
    "        if len(x[\"kwargs\"]) > 0:\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": numpy.\" + name + \" options are unsupported\"\n"
    "        parts : []\n"
    "        for e in x[\"args\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return maps[name] + \"(\" + join_text(parts, \", \") + \")\"\n"
    "    if mod = \"pandas\":\n"
    "        if name = \"Series\":\n"
    "            if len(x[\"args\"]) != 1 or len(x[\"kwargs\"]) != 0:\n"
    "                raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": pandas.Series requires one argument\"\n"
    "            return expr_text(x[\"args\"][0], st)\n"
    "        if name != \"DataFrame\":\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": pandas.\" + name + \" is unsupported\"\n"
    "        if len(x[\"args\"]) != 1 or len(x[\"kwargs\"]) != 0 or x[\"args\"][0][\"t\"] != \"Dict\":\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": pandas.DataFrame requires one dictionary argument\"\n"
    "        d : x[\"args\"][0]\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(d[\"keys\"]):\n"
    "            k : d[\"keys\"][i]\n"
    "            if k[\"t\"] != \"Const\" or k[\"kind\"] != \"string\" or not re_match(\"^[A-Za-z_][A-Za-z0-9_]*$\", k[\"value\"]):\n"
    "                raise st[\"filename\"] + \":\" + str(k[\"line\"]) + \":\" + str(k[\"col\"]) + \": DataFrame column names must be valid string identifiers\"\n"
    "            parts.append(k[\"value\"] + \":\" + expr_text(d[\"values\"][i], st))\n"
    "            i += 1\n"
    "        return \"table(\" + join_text(parts, \", \") + \")\"\n"
    "    return None\n"
    "\n"
    "def transpile(source, filename):\n"
    "    ast : parse(source, filename)\n"
    "    return render(ast, {\"aliases\":ast[\"aliases\"]})\n"
    "\n"
    "def main():\n"
    "    if len(argv) < 2:\n"
    "        raise \"usage: s2p.ie input.py [-o out.ie]\"\n"
    "    inp : None\n"
    "    out : None\n"
    "    i : 1\n"
    "    while i < len(argv):\n"
    "        if argv[i] = \"-o\" or argv[i] = \"--output\":\n"
    "            if i + 1 >= len(argv):\n"
    "                raise \"missing output path\"\n"
    "            out : argv[i + 1]\n"
    "            i += 2\n"
    "        elif argv[i][0] = \"-\":\n"
    "            raise \"unknown option: \" + argv[i]\n"
    "        elif inp = None:\n"
    "            inp : argv[i]\n"
    "            i += 1\n"
    "        else:\n"
    "            raise \"unexpected argument: \" + argv[i]\n"
    "    if inp = None:\n"
    "        raise \"usage: s2p.ie input.py [-o out.ie]\"\n"
    "    result : transpile(read(inp), inp)\n"
    "    if out = None:\n"
    "        write(\"/dev/stdout\", result)\n"
    "    else:\n"
    "        write(out, result)\n"
    "\n"
    "# Run CLI only when this file is the entry script.\n"
    "if re_match(\"s2p\\\\.ie$\", argv[0]):\n"
    "    main()\n"
;
#endif /* SHAKTI_SHAKTI_S2P_SOURCE_H */
